36	/// A server request band: base constant, its members, and the count constant
37	/// that bounds it (`None` for VM, which has no `NR_*` on the Rust side).
38	struct Band {
39	    title: &'static str,
40	    base_name: &'static str,
41	    base: i32,
42	    count: Option<(&'static str, usize)>,
43	    members: Vec<(&'static str, i32)>,
44	}
45	
46	fn bands() -> [Band; 5] {
47	    [
48	        Band {
49	            title: "PM requests",
50	            base_name: "PM_RQ_BASE",
51	            base: callnr::PM_RQ_BASE,
52	            count: Some(("NR_PM_MSGS", callnr::NR_PM_MSGS)),
53	            members: vec![
54	                ("PM_GETPID", callnr::PM_GETPID),
55	                ("PM_FORK", callnr::PM_FORK),
56	                ("PM_EXIT", callnr::PM_EXIT),
57	                ("PM_WAIT", callnr::PM_WAIT),
58	                ("PM_EXEC", callnr::PM_EXEC),
59	            ],
60	        },
61	        Band {
62	            title: "VM requests",
63	            base_name: "VM_RQ_BASE",
64	            base: callnr::VM_RQ_BASE,
65	            count: None,
66	            members: vec![
67	                ("VM_PAGEFAULT", callnr::VM_PAGEFAULT),
68	                ("VM_BRK", callnr::VM_BRK),
69	                ("VM_MMAP", callnr::VM_MMAP),
70	                ("VM_MUNMAP", callnr::VM_MUNMAP),
71	                ("VM_FORK", callnr::VM_FORK),
72	            ],
73	        },
74	        Band {
75	            title: "SEF control messages",
76	            base_name: "SEF_RQ_BASE",
77	            base: callnr::SEF_RQ_BASE,
78	            count: Some(("NR_SEF_MSGS", callnr::NR_SEF_MSGS)),
79	            members: vec![
80	                ("SEF_INIT", callnr::SEF_INIT),
81	                ("SEF_SIGNAL", callnr::SEF_SIGNAL),
82	            ],
83	        },
84	        Band {
85	            title: "DS requests",
86	            base_name: "DS_RQ_BASE",
87	            base: callnr::DS_RQ_BASE,
88	            count: Some(("NR_DS_REQUESTS", callnr::NR_DS_REQUESTS)),
89	            members: vec![
90	                ("DS_PUBLISH", callnr::DS_PUBLISH),
91	                ("DS_RETRIEVE", callnr::DS_RETRIEVE),
92	                ("DS_CHECK", callnr::DS_CHECK),
93	            ],
94	        },
95	        Band {
96	            title: "SCHED requests",
97	            base_name: "SCHED_RQ_BASE",
98	            base: callnr::SCHED_RQ_BASE,
99	            count: Some(("NR_SCHED_MSGS", callnr::NR_SCHED_MSGS)),
100	            members: vec![
101	                ("SCHEDULING_NO_QUANTUM", callnr::SCHEDULING_NO_QUANTUM),
102	                ("SCHEDULING_START", callnr::SCHEDULING_START),
103	                ("SCHEDULING_STOP", callnr::SCHEDULING_STOP),
104	                ("SCHEDULING_SET_NICE", callnr::SCHEDULING_SET_NICE),
105	            ],
106	        },
107	    ]
108	}
