110	/// Render `minix/callnr.h`.
111	pub fn render() -> String {
112	    let mut f = CFile::new(
113	        "Kernel-call numbers, server request bands, and their payload constants.",
114	        &["kernel-shared/src/callnr.rs"],
115	    );
116	    f.guard_open(GUARD);
117	
118	    f.blank();
119	    f.include(
120	        "minix/ipc.h",
121	        "NOTIFY_MESSAGE, for the band ordering checks",
122	    );
123	
124	    f.block_comment(&[
125	        "Deviation from MINIX 3: its <minix/callnr.h> holds POSIX syscall numbers",
126	        "and keeps server request numbers in <minix/com.h>. minix.rs has no POSIX",
127	        "call-number layer -- a libc wrapper builds a server request directly --",
128	        "so this header carries the kernel calls and the request bands together.",
129	        "",
130	        "Payload byte offsets are not emitted yet: on the Rust side they live in",
131	        "doc comments rather than constants. The first musl wrapper (slice 5.6) is",
132	        "the forcing function for promoting them to real constants.",
133	    ]);
134	
135	    f.section("kernel calls");
136	    f.define_hex("KERNEL_CALL", callnr::KERNEL_CALL.into());
137	    f.blank();
138	    for (name, value) in kernel_calls() {
139	        f.define_hex(name, value.into());
140	    }
141	    f.blank();
142	    f.define_raw(
143	        "NR_KERN_CALLS",
144	        &format!(
145	            "{}   /* kernel-shared: NR_KERN_CALLS_PHASE4 */",
146	            callnr::NR_KERN_CALLS_PHASE4
147	        ),
148	    );
149	    f.define_dec("NR_SYS_CALLS", callnr::NR_SYS_CALLS as i64);
150	
151	    f.section("kernel-call payload constants");
152	    f.define_dec("GET_WHOAMI", callnr::GET_WHOAMI.into());
153	    f.define_dec("SYS_GETINFO_NAME_LEN", callnr::SYS_GETINFO_NAME_LEN as i64);
154	    f.define_dec("EXEC_NAME_LEN", callnr::EXEC_NAME_LEN as i64);
155	    f.define_dec("PRIVCTL_SET_USER", callnr::PRIVCTL_SET_USER.into());
156	    f.define_dec("SCHEDCTL_FLAG_KERNEL", callnr::SCHEDCTL_FLAG_KERNEL.into());
157	
158	    f.section("SYS_VMCTL subcalls");
159	    f.define_dec("VMCTL_PT_MAP", callnr::VMCTL_PT_MAP.into());
160	    f.define_dec("VMCTL_PT_UNMAP", callnr::VMCTL_PT_UNMAP.into());
161	    f.define_dec(
162	        "VMCTL_CLEAR_PAGEFAULT",
163	        callnr::VMCTL_CLEAR_PAGEFAULT.into(),
164	    );
165	    f.define_dec("VMCTL_GET_PAGEFAULT", callnr::VMCTL_GET_PAGEFAULT.into());
166	    f.define_dec("VMCTL_VMINHIBIT_SET", callnr::VMCTL_VMINHIBIT_SET.into());
167	    f.define_dec(
168	        "VMCTL_VMINHIBIT_CLEAR",
169	        callnr::VMCTL_VMINHIBIT_CLEAR.into(),
170	    );
171	    f.define_dec("NR_VMCTL_SUBCALLS", callnr::NR_VMCTL_SUBCALLS as i64);
172	    f.blank();
173	    f.define_dec("VMCTL_PROT_WRITE", callnr::VMCTL_PROT_WRITE.into());
174	    f.define_dec("VMCTL_PROT_EXEC", callnr::VMCTL_PROT_EXEC.into());
175	
176	    for band in bands() {
177	        f.section(band.title);
178	        f.define_hex(band.base_name, band.base.into());
179	        for (name, value) in &band.members {
180	            f.define_hex(name, (*value).into());
181	        }
182	        if let Some((count_name, count)) = band.count {
183	            f.define_dec(count_name, count as i64);
184	        }
185	    }
186	
187	    f.section("band ordering");
188	    f.block_comment(&[
189	        "Mirrors the `const _: () = assert!(..)` guards in callnr.rs: every band",
190	        "sits above the previous one and entirely below NOTIFY_MESSAGE, so no",
191	        "server request can ever be mistaken for a kernel NOTIFY.",
192	    ]);
193	    f.static_assert(
194	        "NR_SYS_CALLS >= NR_KERN_CALLS",
195	        "the privilege call mask is narrower than the kernel-call set",
196	    );
197	    f.static_assert(
198	        "PM_RQ_BASE > KERNEL_CALL + NR_KERN_CALLS - 1",
199	        "the PM band overlaps the kernel calls",
200	    );
201	    f.static_assert(
202	        "PM_RQ_BASE + NR_PM_MSGS - 1 < VM_RQ_BASE",
203	        "the PM band overlaps the VM band",
204	    );
205	    f.static_assert("SEF_RQ_BASE > VM_FORK", "the SEF band overlaps the VM band");
206	    f.static_assert(
207	        "DS_RQ_BASE > SEF_RQ_BASE + NR_SEF_MSGS - 1",
208	        "the DS band overlaps the SEF band",
209	    );
210	    f.static_assert(
211	        "SCHED_RQ_BASE > DS_RQ_BASE + NR_DS_REQUESTS - 1",
212	        "the SCHED band overlaps the DS band",
213	    );
214	    f.static_assert(
215	        "SCHED_RQ_BASE + NR_SCHED_MSGS - 1 < NOTIFY_MESSAGE",
216	        "a server request number collides with NOTIFY_MESSAGE",
217	    );
218	
219	    f.guard_close(GUARD);
220	    f.finish()
221	}
