223	#[cfg(test)]
224	mod tests {
225	    use super::*;
226	    use crate::builder;
227	
228	    #[test]
229	    fn kernel_calls_render_from_live_constants() {
230	        let text = render();
231	        for (name, value) in kernel_calls() {
232	            assert_eq!(
233	                builder::define_value(&text, name).as_deref(),
234	                Some(format!("0x{value:X}").as_str()),
235	                "{name} did not render from its Rust constant"
236	            );
237	        }
238	    }
239	
240	    #[test]
241	    fn the_kernel_call_list_is_complete_and_contiguous() {
242	        let calls = kernel_calls();
243	        assert_eq!(calls.len(), callnr::NR_KERN_CALLS_PHASE4);
244	        for (i, (name, value)) in calls.into_iter().enumerate() {
245	            assert_eq!(
246	                value,
247	                callnr::KERNEL_CALL + i as i32,
248	                "{name} is out of order"
249	            );
250	        }
251	    }
252	
253	    #[test]
254	    fn every_band_base_member_and_count_appears() {
255	        let text = render();
256	        for band in bands() {
257	            assert_eq!(
258	                builder::define_value(&text, band.base_name).as_deref(),
259	                Some(format!("0x{:X}", band.base).as_str())
260	            );
261	            for (name, value) in &band.members {
262	                assert_eq!(
263	                    builder::define_value(&text, name).as_deref(),
264	                    Some(format!("0x{value:X}").as_str()),
265	                    "{name} missing from the {} band",
266	                    band.title
267	                );
268	            }
269	            if let Some((count_name, count)) = band.count {
270	                assert_eq!(
271	                    builder::define_value(&text, count_name).as_deref(),
272	                    Some(count.to_string().as_str())
273	                );
274	            }
275	        }
276	    }
277	
278	    /// VM is the one band with no `NR_*` count on the Rust side, so its guard
279	    /// names the last member instead. Pin that so a future `NR_VM_MSGS` is a
280	    /// deliberate change here rather than a silent gap.
281	    #[test]
282	    fn the_vm_band_has_no_count_constant() {
283	        let vm = bands()
284	            .into_iter()
285	            .find(|b| b.base_name == "VM_RQ_BASE")
286	            .unwrap();
287	        assert!(vm.count.is_none());
288	        assert!(render().contains("SEF_RQ_BASE > VM_FORK"));
289	    }
290	
291	    /// `NR_KERN_CALLS_PHASE4` is a phase-scoped Rust name; the C header, which
292	    /// freezes at slice 5.6, spells it `NR_KERN_CALLS` and records the origin.
293	    #[test]
294	    fn nr_kern_calls_is_renamed_with_provenance() {
295	        let text = render();
296	        assert!(text.contains(&format!(
297	            "#define NR_KERN_CALLS            {}   /* kernel-shared: NR_KERN_CALLS_PHASE4 */",
298	            callnr::NR_KERN_CALLS_PHASE4
299	        )));
300	        assert!(builder::define_value(&text, "NR_KERN_CALLS_PHASE4").is_none());
301	    }
302	}
