1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! `minix/com.h` — process numbers and the endpoints derived from them.
4	
5	use minixrs_kernel_shared::{ProcNr, com, error};
6	
7	use crate::builder::CFile;
8	
9	/// Include guard for the generated header.
10	pub const GUARD: &str = "_MINIX_COM_H";
11	
12	/// Every process that gets a `_PROC_NR` / `_EP` macro pair, in slot order.
13	///
14	/// The C name is spelled here rather than taken from the Rust constant name
15	/// because the kernel tasks are `com::SYSTEM` (no suffix) on the Rust side but
16	/// must be `SYSTEM_PROC_NR` / `SYSTEM_EP` in C, where a bare `SYSTEM` would be
17	/// an unpleasant macro to inflict on a C translation unit.
18	fn processes() -> [(&'static str, ProcNr); 16] {
19	    [
20	        ("ASYNCM", com::ASYNCM),
21	        ("IDLE", com::IDLE),
22	        ("CLOCK", com::CLOCK),
23	        ("SYSTEM", com::SYSTEM),
24	        ("HARDWARE", com::HARDWARE),
25	        ("PM", com::PM_PROC_NR),
26	        ("VFS", com::VFS_PROC_NR),
27	        ("RS", com::RS_PROC_NR),
28	        ("MEM", com::MEM_PROC_NR),
29	        ("TTY", com::TTY_PROC_NR),
30	        ("DS", com::DS_PROC_NR),
31	        ("MFS", com::MFS_PROC_NR),
32	        ("VM", com::VM_PROC_NR),
33	        ("PFS", com::PFS_PROC_NR),
34	        ("SCHED", com::SCHED_PROC_NR),
35	        ("INIT", com::INIT_PROC_NR),
36	    ]
37	}
38	
39	/// Render `minix/com.h`.
40	pub fn render() -> String {
41	    let mut f = CFile::new(
42	        "Process numbers, boot endpoints, and process-table capacities.",
43	        &["kernel-shared/src/com.rs", "kernel-shared/src/error.rs"],
44	    );
45	    f.guard_open(GUARD);
46	
47	    f.blank();
48	    f.include(
49	        "minix/ipc.h",
50	        "endpoint_t and the _ENDPOINT* packing macros",
51	    );
52	
53	    f.section("process-table capacities");
54	    f.define_dec("NR_TASKS", com::NR_TASKS as i64);
55	    f.define_dec("NR_PROCS", com::NR_PROCS as i64);
56	    f.define_dec("NR_SYS_PROCS", com::NR_SYS_PROCS as i64);
57	    f.define_dec("NR_BOOT_PROCS", com::NR_BOOT_PROCS as i64);
58	
59	    f.section("success sentinel");
60	    f.block_comment(&[
61	        "MINIX 3 keeps OK in <minix/const.h>; minix.rs defines it alongside the",
62	        "errnos in kernel-shared/src/error.rs. It lives here so a C file that",
63	        "checks an IPC result does not have to include <minix/errno.h> as well.",
64	    ]);
65	    f.define_dec("OK", error::OK.into());
66	
67	    f.section("processes");
68	    f.block_comment(&[
69	        "Every process below has TWO macros, and they are NOT interchangeable:",
70	        "",
71	        "    <NAME>_PROC_NR   the process-table slot (NEGATIVE for kernel tasks)",
72	        "    <NAME>_EP        the boot endpoint -- what belongs in an IPC call",
73	        "",
74	        "They differ for the kernel tasks because minix.rs sign-extends the",
75	        "endpoint proc field instead of using MINIX 3's offset bias (see",
76	        "minix/ipc.h). Naming a task by its _PROC_NR in an IPC call is a bug.",
77	        "",
78	        "The _EP values are computed by calling com::boot_endpoint() in the",
79	        "generator: no equivalent Rust constant exists, and deriving them here is",
80	        "exactly what this tool is for.",
81	    ]);
82	    for (name, nr) in processes() {
83	        f.define_dec(&format!("{name}_PROC_NR"), nr.get().into());
84	        f.define_ep(&format!("{name}_EP"), com::boot_endpoint(nr));
85	    }
86	
87	    f.block_comment(&[
88	        "Sentinel proc number for an MXBI archive module that is resolvable by",
89	        "name but never boot-loaded (the exec target). Not a process.",
90	    ]);
91	    f.define_dec("EXEC_ONLY_PROC_NR", com::EXEC_ONLY_PROC_NR.into());
92	
93	    f.block_comment(&[
94	        "Deliberately not emitted, each for want of a C consumer:",
95	        "  * STUB_[A-D]_PROC_NR / NR_STUB_PROCS -- the demo stubs are scoped to",
96	        "    the kernel's `boot-stubs` cargo feature.",
97	        "  * NR_SERVED_PROCS -- sizes the Rust servers' per-process tables.",
98	        "  * message::USER_VA_TOP and sys_limits::* -- kernel-internal caps.",
99	        "  * signal numbers -- musl's <signal.h> is authoritative and already",
100	        "    agrees with kernel-shared/src/signal.rs.",
101	    ]);
102	
103	    f.section("endpoint packing self-check");
104	    f.block_comment(&[
105	        "The C decode macros in minix/ipc.h are hand-written; the _EP values are",
106	        "Rust-computed. These assertions check one against the other at compile",
107	        "time, in every translation unit, with no libc and no sysroot.",
108	    ]);
109	    for name in ["SYSTEM", "HARDWARE", "CLOCK", "PM", "VFS", "INIT"] {
110	        f.static_assert(
111	            &format!("{name}_EP == _ENDPOINT(0, {name}_PROC_NR)"),
112	            &format!("{name}_EP disagrees with the _ENDPOINT packing macro"),
113	        );
114	        f.static_assert(
115	            &format!("_ENDPOINT_P({name}_EP) == {name}_PROC_NR"),
116	            &format!("_ENDPOINT_P does not round-trip {name}_EP"),
117	        );
118	        f.static_assert(
119	            &format!("_ENDPOINT_G({name}_EP) == 0"),
120	            &format!("{name}_EP is not a generation-0 boot endpoint"),
121	        );
122	    }
123	
124	    f.guard_close(GUARD);
125	    f.finish()
126	}
