128	#[cfg(test)]
129	mod tests {
130	    use super::*;
131	    use crate::{builder, ipc_h};
132	
133	    #[test]
134	    fn every_process_has_both_a_proc_nr_and_an_ep() {
135	        let text = render();
136	        for (name, _) in processes() {
137	            assert!(
138	                text.contains(&format!("#define {name}_PROC_NR")),
139	                "{name}_PROC_NR missing"
140	            );
141	            assert!(
142	                text.contains(&format!("#define {name}_EP")),
143	                "{name}_EP missing"
144	            );
145	        }
146	    }
147	
148	    #[test]
149	    fn endpoints_match_boot_endpoint() {
150	        let text = render();
151	        for (name, nr) in processes() {
152	            let ep = com::boot_endpoint(nr);
153	            assert_eq!(
154	                builder::define_value(&text, &format!("{name}_EP")).as_deref(),
155	                Some(format!("((endpoint_t) {ep})").as_str()),
156	                "{name}_EP is not boot_endpoint({nr})"
157	            );
158	            assert_eq!(
159	                builder::define_value(&text, &format!("{name}_PROC_NR")).as_deref(),
160	                Some(fmt_dec(nr.get()).as_str()),
161	                "{name}_PROC_NR is not the table slot"
162	            );
163	        }
164	    }
165	
166	    /// Mirror of `CFile::define_dec`'s negative-parenthesizing rule.
167	    fn fmt_dec(v: i32) -> String {
168	        if v < 0 {
169	            format!("({v})")
170	        } else {
171	            v.to_string()
172	        }
173	    }
174	
175	    /// The whole point of the two-macro split: for kernel tasks the endpoint is
176	    /// not the proc number, so emitting only one of them would be a footgun.
177	    #[test]
178	    fn task_endpoints_differ_from_their_proc_numbers() {
179	        for name in ["ASYNCM", "IDLE", "CLOCK", "SYSTEM", "HARDWARE"] {
180	            let (_, nr) = processes().into_iter().find(|p| p.0 == name).unwrap();
181	            assert_ne!(com::boot_endpoint(nr), nr.get(), "{name}");
182	        }
183	        // ...while server slots do coincide, which is why the distinction is
184	        // easy to miss without the comment the header carries.
185	        let (_, pm) = processes().into_iter().find(|p| p.0 == "PM").unwrap();
186	        assert_eq!(com::boot_endpoint(pm), pm.get());
187	    }
188	
189	    #[test]
190	    fn negative_proc_numbers_are_parenthesized() {
191	        let text = render();
192	        assert!(text.contains(&format!("({})", com::SYSTEM.get())));
