3	//! `minix/ipc.h` — the message struct, endpoint packing, and IPC primitives.
4	
5	use minixrs_kernel_shared::{Message, endpoint, ipc_const};
6	
7	use crate::builder::CFile;
8	
9	/// Include guard for the generated header.
10	pub const GUARD: &str = "_MINIX_IPC_H";
11	
12	/// Layout of [`Message`], measured rather than assumed.
13	///
14	/// Every number the header pins comes from here, so the generator can never
15	/// hardcode a stale 104/8/8 and a Rust-side layout change surfaces in the C.
16	struct MessageLayout {
17	    size: usize,
18	    align: usize,
19	    m_source_off: usize,
20	    m_type_off: usize,
21	    payload_off: usize,
22	    payload_len: usize,
23	}
24	
25	impl MessageLayout {
26	    fn measure() -> Self {
27	        let msg = Message {
28	            m_source: 0,
29	            m_type: 0,
30	            payload: [0; 96],
31	        };
32	        let base = (&raw const msg) as usize;
33	        Self {
34	            size: size_of::<Message>(),
35	            align: align_of::<Message>(),
36	            m_source_off: (&raw const msg.m_source) as usize - base,
37	            m_type_off: (&raw const msg.m_type) as usize - base,
38	            payload_off: (&raw const msg.payload) as usize - base,
39	            payload_len: msg.payload.len(),
40	        }
41	    }
42	}
43	
44	/// Render `minix/ipc.h`.
45	pub fn render() -> String {
46	    let l = MessageLayout::measure();
47	    let mut f = CFile::new(
48	        "IPC message format, endpoint packing, and the IPC primitive numbers.",
49	        &[
50	            "kernel-shared/src/message.rs",
51	            "kernel-shared/src/endpoint.rs",
52	            "kernel-shared/src/ipc_const.rs",
53	        ],
54	    );
55	    f.guard_open(GUARD);
56	
57	    f.block_comment(&[
58	        "This header deliberately includes nothing in the common case: it",
59	        "describes a kernel ABI and must be usable from freestanding C as well as",
60	        "from musl user space. The one thing it needs is offsetof, which comes",
61	        "from a compiler builtin under a private name -- both to avoid depending",
62	        "on <stddef.h> and to avoid ever colliding with the C library's own",
63	        "offsetof macro.",
64	        "",
65	        "The fallback exists for a hypothetical non-GNU-flavoured compiler; the",
66	        "supported toolchain is clang (phase-5 decision D10).",
67	    ]);
68	    f.line("#if defined(__GNUC__) || defined(__clang__)");
69	    f.define_raw("_MINIX_OFFSETOF(t, m)", "__builtin_offsetof(t, m)");
70	    f.line("#else");
71	    f.include("stddef.h", "offsetof");
72	    f.define_raw("_MINIX_OFFSETOF(t, m)", "offsetof(t, m)");
73	    f.line("#endif");
74	
75	    f.section("endpoints");
76	    f.line("typedef int endpoint_t;");
77	    f.static_assert(
78	        "sizeof(int) == 4",
79	        "the minix.rs ABI assumes a 32-bit int for endpoint_t",
80	    );
81	
82	    f.blank();
83	    f.define_dec("ENDPOINT_GEN_SHIFT", endpoint::ENDPOINT_GEN_SHIFT.into());
84	    f.define_raw(
85	        "ENDPOINT_PROC_MASK",
86	        &format!("0x{:x}", endpoint::ENDPOINT_PROC_MASK),
87	    );
88	    f.define_dec(
89	        "ENDPOINT_MAX_GENERATION",
90	        endpoint::ENDPOINT_MAX_GENERATION.into(),
91	    );
92	    f.define_dec(
93	        "ENDPOINT_SLOT_TOP",
94	        endpoint::ENDPOINT_SLOT_TOP.get().into(),
95	    );
96	
97	    f.blank();
98	    f.define_ep("ANY", endpoint::ANY);
99	    f.define_ep("NONE", endpoint::NONE);
100	    f.define_ep("SELF", endpoint::SELF);
101	
102	    f.block_comment(&[
103	        "Endpoint packing. minix.rs deviates from MINIX 3 deliberately: the proc",
104	        "field is SIGN-EXTENDED from bit ENDPOINT_GEN_SHIFT-1 to recover negative",
105	        "kernel-task slots, rather than MINIX 3's MAX_NR_TASKS offset bias. These",
106	        "mirror endpoint.rs::{make_endpoint, endpoint_proc, endpoint_gen}.",
107	        "",
108	        "The consequence is that _ENDPOINT(0, p) != p for negative p, which is why",
109	        "minix/com.h gives every process both a _PROC_NR and an _EP macro.",
110	    ]);
111	    f.line("#define _ENDPOINT(g, p)  (((g) << ENDPOINT_GEN_SHIFT) | ((p) & ENDPOINT_PROC_MASK))");
112	    f.line("#define _ENDPOINT_G(e)   ((e) >> ENDPOINT_GEN_SHIFT)");
113	    f.line("#define _ENDPOINT_P(e)                                                   \\");
114	    f.line("    ((((e) & ENDPOINT_PROC_MASK) & (1 << (ENDPOINT_GEN_SHIFT - 1)))      \\");
115	    f.line("        ? (((e) & ENDPOINT_PROC_MASK) | ~ENDPOINT_PROC_MASK)             \\");
116	    f.line("        : ((e) & ENDPOINT_PROC_MASK))");
117	
118	    f.section("message");
119	    f.block_comment(&[
120	        "The IPC message. Laid out to match kernel-shared's #[repr(C, align(8))]",
121	        "Message exactly; the assertions below are generated from the live Rust",
122	        "type, so a layout change on either side fails to compile rather than",
123	        "silently corrupting every IPC call.",
124	        "",
125	        "C11 forbids an alignment specifier on a struct type declaration, so the",
126	        "_Alignas rides the first member -- a struct's alignment is the maximum of",
127	        "its members', which yields the required 8.",
128	    ]);
129	    f.line("struct message {");
130	    f.line("    _Alignas(8) endpoint_t m_source;   /* set by the kernel on delivery */");
131	    f.line("    int                    m_type;     /* call number out, result back  */");
132	    f.line(&format!(
133	        "    unsigned char          payload[{}];",
134	        l.payload_len
135	    ));
136	    f.line("};");
137	    f.line("typedef struct message message;");
138	
139	    f.blank();
140	    f.static_assert(
141	        &format!("sizeof(message) == {}", l.size),
142	        "message size drifted from kernel-shared Message",
143	    );
144	    f.static_assert(
145	        &format!("_Alignof(message) == {}", l.align),
146	        "message alignment drifted from kernel-shared Message",
147	    );
148	    f.static_assert(
149	        &format!("_MINIX_OFFSETOF(message, m_source) == {}", l.m_source_off),
150	        "m_source offset drifted from kernel-shared Message",
151	    );
152	    f.static_assert(
153	        &format!("_MINIX_OFFSETOF(message, m_type) == {}", l.m_type_off),
154	        "m_type offset drifted from kernel-shared Message",
155	    );
156	    f.static_assert(
157	        &format!("_MINIX_OFFSETOF(message, payload) == {}", l.payload_off),
158	        "payload offset drifted from kernel-shared Message",
159	    );
160	
161	    f.section("IPC primitives");
162	    f.block_comment(&[
163	        "Primitive numbers for the IPC trap. The register that carries them is",
164	        "part of the per-architecture trap ABI -- see kernel-shared/src/ipc_const.rs",
165	        "and the minix-ipc crate, which are authoritative.",
166	    ]);
167	    f.define_dec("SEND", ipc_const::SEND.into());
168	    f.define_dec("RECEIVE", ipc_const::RECEIVE.into());
169	    f.define_dec("SENDREC", ipc_const::SENDREC.into());
170	    f.define_dec("NOTIFY", ipc_const::NOTIFY.into());
171	    f.define_dec("SENDNB", ipc_const::SENDNB.into());
172	    f.define_dec("SENDA", ipc_const::SENDA.into());
173	    f.define_dec("MINIX_KERNINFO", ipc_const::MINIX_KERNINFO.into());
174	    f.define_hex("NOTIFY_MESSAGE", ipc_const::NOTIFY_MESSAGE.into());
175	
176	    f.guard_close(GUARD);
177	    f.finish()
178	}
179	
180	#[cfg(test)]
181	mod tests {
182	    use super::*;
183	
184	    /// The D8-mandated layout snapshot: the generated text must agree with
185	    /// `Message`'s own const assertions, and the generator must derive the
186	    /// numbers rather than typing them in.
187	    #[test]
188	    fn pins_the_live_message_layout() {
189	        let text = render();
190	        let l = MessageLayout::measure();
191	
192	        assert!(text.contains(&format!("sizeof(message) == {}", size_of::<Message>())));
193	        assert!(text.contains(&format!("_Alignof(message) == {}", align_of::<Message>())));
194	        assert!(text.contains(&format!(
195	            "_MINIX_OFFSETOF(message, payload) == {}",
196	            l.payload_off
197	        )));
198	        assert!(text.contains(&format!(
199	            "unsigned char          payload[{}];",
200	            l.payload_len
201	        )));
202	
203	        // The ABI numbers themselves, pinned so a layout change is a deliberate
204	        // edit in two places (here and message.rs's const asserts).
205	        assert_eq!(l.size, 104);
206	        assert_eq!(l.align, 8);
207	        assert_eq!(l.m_source_off, 0);
208	        assert_eq!(l.m_type_off, 4);
209	        assert_eq!(l.payload_off, 8);
210	        assert_eq!(l.payload_len, 96);
211	    }
212	
213	    /// The ABI header must be includable from freestanding C. Apple's clang
214	    /// redirects `<stddef.h>` to the system header for any `*-musl` triple, so
215	    /// an unconditional include also breaks a hermetic, sysroot-less check.
216	    #[test]
217	    fn needs_no_header_under_a_gnu_flavoured_compiler() {
218	        let text = render();
219	        let gnu_arm = text
220	            .split("#if defined(__GNUC__) || defined(__clang__)")
221	            .nth(1)
222	            .and_then(|s| s.split("#else").next())
223	            .expect("the offsetof fallback block");
224	        assert!(!gnu_arm.contains("#include"));
225	        assert!(gnu_arm.contains("__builtin_offsetof"));
226	        assert!(text.contains("_MINIX_OFFSETOF(message, payload)"));
227	    }
228	
229	    #[test]
230	    fn alignas_rides_the_first_member() {
231	        // C11 rejects an alignment specifier on the struct type declaration.
232	        let text = render();
233	        assert!(text.contains("_Alignas(8) endpoint_t m_source;"));
234	        assert!(!text.contains("_Alignas(8) struct"));
235	    }
236	
237	    #[test]
238	    fn ipc_primitives_render_from_live_constants() {
239	        let text = render();
240	        for (name, value) in [
241	            ("SENDREC", ipc_const::SENDREC),
242	            ("NOTIFY", ipc_const::NOTIFY),
243	            ("SENDNB", ipc_const::SENDNB),
244	        ] {
245	            assert!(text.contains(&format!("#define {name:<24} {value}")));
246	        }
247	        assert!(text.contains(&format!("0x{:X}", ipc_const::NOTIFY_MESSAGE)));
248	    }
249	
250	    #[test]
251	    fn endpoint_sentinels_render_from_live_constants() {
252	        let text = render();
253	        assert!(text.contains(&format!(
254	            "#define ANY                      ((endpoint_t) {})",
255	            endpoint::ANY
256	        )));
257	        assert!(text.contains(&format!(
258	            "#define NONE                     ((endpoint_t) {})",
259	            endpoint::NONE
260	        )));
261	        assert!(text.contains(&format!(
262	            "#define SELF                     ((endpoint_t) {})",
263	            endpoint::SELF
264	        )));
265	    }
266	
267	    /// The header must not restate the trap register: `ipc_const.rs`'s own
268	    /// comment on that point is wrong (it says `x16`; the kernel reads `x1`),
269	    /// and correcting it belongs to slice 5.1.
270	    #[test]
271	    fn makes_no_trap_register_claim() {
272	        let text = render();
273	        assert!(!text.contains("x16"));
274	        assert!(!text.contains("x1 "));
275	    }
276	}
