1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Append-only writer for a generated C file.
4	//!
5	//! Deliberately not built on `core::fmt::Write`: `write!` into a `String`
6	//! returns a `Result` that has to be handled at every one of a few hundred call
7	//! sites for an error that cannot occur. `push_str` plus `format!` keeps the
8	//! renderers readable.
9	
10	/// Column the value in a `#define` is padded out to.
11	const DEFINE_WIDTH: usize = 24;
12	
13	/// A C translation unit or header under construction.
14	pub struct CFile {
15	    out: String,
16	}
17	
18	impl CFile {
19	    /// Start a file with the shared SPDX + generated-artifact banner.
20	    ///
21	    /// `sources` names the `kernel-shared` files the content is derived from,
22	    /// so a reader of the generated header knows where the real definition
23	    /// lives.
24	    pub fn new(title: &str, sources: &[&str]) -> Self {
25	        let mut f = Self { out: String::new() };
26	        f.line("/* SPDX-License-Identifier: BSD-3-Clause */");
27	        f.line("/* Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors */");
28	        f.line("/*");
29	        f.line(" * GENERATED FILE -- DO NOT EDIT.");
30	        f.line(" *");
31	        f.line(&format!(" * {title}"));
32	        f.line(" *");
33	        f.line(" * Produced by tools/gen-c-headers from the live constants in the");
34	        f.line(" * minixrs-kernel-shared crate:");
35	        for src in sources {
36	            f.line(&format!(" *     {src}"));
37	        }
38	        f.line(" * Regenerate with `cargo gen-c-headers`.");
39	        f.line(" *");
40	        f.line(" * A build artifact, deliberately never committed (phase-5 decision D8):");
41	        f.line(" * the Rust constants are the single source of truth, so drift is");
42	        f.line(" * impossible by construction rather than caught by a test.");
43	        f.line(" */");
44	        f
45	    }
46	
47	    /// Append one line.
48	    pub fn line(&mut self, s: &str) {
49	        self.out.push_str(s);
50	        self.out.push('\n');
51	    }
52	
53	    /// Append a blank line.
54	    pub fn blank(&mut self) {
55	        self.out.push('\n');
56	    }
57	
58	    /// Open an include guard.
59	    pub fn guard_open(&mut self, guard: &str) {
60	        self.blank();
61	        self.line(&format!("#ifndef {guard}"));
62	        self.line(&format!("#define {guard}"));
63	    }
64	
65	    /// Close an include guard opened by [`CFile::guard_open`].
66	    pub fn guard_close(&mut self, guard: &str) {
67	        self.blank();
68	        self.line(&format!("#endif /* {guard} */"));
69	    }
70	
71	    /// A one-line section banner.
72	    pub fn section(&mut self, title: &str) {
73	        self.blank();
74	        self.line(&format!("/* ---- {title} ---- */"));
75	    }
76	
77	    /// A multi-line block comment.
78	    pub fn block_comment(&mut self, lines: &[&str]) {
79	        self.blank();
80	        self.line("/*");
81	        for l in lines {
82	            if l.is_empty() {
83	                self.line(" *");
84	            } else {
85	                self.line(&format!(" * {l}"));
86	            }
87	        }
88	        self.line(" */");
89	    }
90	
91	    /// `#include <header>` with a trailing rationale comment.
92	    pub fn include(&mut self, header: &str, why: &str) {
93	        self.line(&format!("#include <{header}>   /* {why} */"));
94	    }
95	
96	    /// `#define NAME value` in decimal. Negative values are parenthesized, so
97	    /// `x-SYSTEM_PROC_NR` cannot mis-parse at the use site.
98	    pub fn define_dec(&mut self, name: &str, value: i64) {
99	        let text = if value < 0 {
100	            format!("({value})")
101	        } else {
102	            value.to_string()
103	        };
104	        self.define_raw(name, &text);
105	    }
106	
107	    /// `#define NAME 0xVALUE`, for call numbers and request bands.
108	    pub fn define_hex(&mut self, name: &str, value: i64) {
109	        assert!(value >= 0, "hex defines are for non-negative values");
