138	/// Parse the `#define NAME value` lines out of a rendered file.
139	///
140	/// Object-like defines only: a function-like `#define NAME(args) ...` has no
141	/// value column to report, so it is skipped. Used by the cross-artifact tests
142	/// to check for duplicate names and non-identifier spellings.
143	pub fn defines(text: &str) -> Vec<(String, String)> {
144	    text.lines()
145	        .filter_map(|line| line.strip_prefix("#define "))
146	        .filter_map(|rest| {
147	            let (name, value) = rest.split_once(char::is_whitespace)?;
148	            if name.contains('(') {
149	                return None; // function-like macro
150	            }
151	            Some((name.to_string(), value.trim().to_string()))
152	        })
153	        .collect()
154	}
